const D = { energy:.6, density:.5, scale:1, hue:38, speed:1, x:.5, y:.5, alpha:.85, softness:.6, style:'warm', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const t = K.t;
const drift = 0.9*Math.sin(t*0.61) + 0.5*Math.sin(t*1.43+1.7) + 0.32*Math.sin(t*2.29);
const swell = (K.swell!=null ? K.swell : 0.5+0.5*Math.sin(t*0.4));
const treb = A.treble||0, bass = A.bass||0;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };

const st = P.style;
// palette generator: returns [h,s] for orb index
function orbCol(i){
  const r = fr(i*7+3);
  if (st==='anamorphic') return [ (P.hue+200 + r*30)%360, 34 ];
  if (st==='jewel')      return [ (r*360)|0, 78 ];
  if (st==='pastel')     return [ (P.hue + (r-0.5)*120 +360)%360, 30 ];
  if (st==='mono')       return [ 40, 6 ];
  return [ (P.hue + (r-0.5)*46 + 360)%360, 55 ]; // warm
}
const oval = st==='anamorphic';

push();
// soft diffusion veil (broad ADD lift -> emits, carries luminance)
blendMode(ADD); noStroke();
const veilC = st==='mono' ? [40,6] : st==='anamorphic' ? [210,22] : [ (P.hue+18)%360, 30 ];
const vA = (10 + 22*P.energy) * (0.7+0.4*swell) * P.alpha;
for (let g=5; g>=1; g--){
  fill(veilC[0], veilC[1], 100, vA*(g/5)*0.5);
  ellipse(width*(0.5+0.06*Math.sin(t*0.18)), height*(0.52+0.05*drift), width*1.3*(g/5)+width*0.3, height*1.2*(g/5)+height*0.3);
}

// defocused orbs
const N = Math.round(10 + 46*P.density);
for (let i=0;i<N;i++){
  const spd = 0.02 + 0.05*fr(i*3+1);
  const ax = (fr(i*3+1)*1.2-0.1), ay=(fr(i*3+2)*1.2-0.1);
  const ox = width*(ax + 0.05*Math.sin(t*spd*P.speed + i) + 0.02*drift);
  const oy = height*(ay + 0.05*Math.cos(t*spd*1.3*P.speed + i*1.7));
  const base = u*(0.03 + 0.12*fr(i*3+3)) * P.scale;
  const sz = base*(1 + 0.9*P.softness);
  const col = orbCol(i);
  const tw = 0.6 + 0.4*Math.sin(t*(0.2+0.3*fr(i+5)) + i);   // slow twinkle (non-strobe)
  const spark = st==='jewel'||st==='warm' ? treb*0.4 : 0;
  const a0 = (16 + 40*P.energy) * P.alpha * tw * (1+spark);
  const wo = oval ? 2.6 : 1;
  // pre-blur look: layered concentric fills
  for (let r=5; r>=1; r--){
    const rr = sz*(r/5);
    fill(col[0], col[1]*(0.8+0.1*r), 100, a0*(r/5)*0.42);
    ellipse(ox, oy, rr*wo, rr/(oval?1.0:1));
  }
  // bright cat's-eye rim on the larger orbs
  if (base > u*0.08){
    noFill(); stroke(col[0], col[1]*0.6, 100, a0*1.1); strokeWeight(Math.max(1, sz*0.03));
    ellipse(ox, oy, sz*0.86*wo, sz*0.86); noStroke();
  }
}

// a few hero orbs with real blur (few shapes only)
const hero = Math.round(2 + 2*P.density);
for (let i=0;i<hero;i++){
  const ph = t*(0.03+0.02*fr(i+20))*P.speed + i*2.1;
  const ox = width*(0.5 + 0.42*Math.sin(ph) );
  const oy = height*(0.5 + 0.38*Math.cos(ph*1.27+1.1));
  const col = orbCol(i+40);
  const sz = u*(0.16+0.12*fr(i+21))*P.scale*(1+0.6*P.softness);
  drawingContext.shadowBlur = sz*0.7; drawingContext.shadowColor='rgba(255,255,255,0.35)';
  fill(col[0], col[1]*0.7, 100, (14+22*P.energy)*P.alpha*(0.7+0.4*swell)*(1+bass*0.3));
  ellipse(ox, oy, sz*(oval?2.6:1), sz);
  drawingContext.shadowBlur = 0;
}

pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
